<style>.section-label{color:var(--primary-deep);font-size:12px;font-weight:700;letter-spacing:.3em;text-transform:uppercase}.cat-session{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-bottom:30px;padding:20px 24px;border:1px solid var(--border);border-radius:22px;background:var(--gradient-cool)}.cat-session form{margin:0}.cat-session .btn{border:0;cursor:pointer}.event-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.event-card{display:flex;flex-direction:column;overflow:hidden;border:1px solid var(--border);border-radius:26px;background:#fff;transition:.4s var(--ease)}.event-card:hover{transform:translateY(-5px);border-color:var(--primary);box-shadow:var(--shadow-elegant)}.event-card img{width:100%;height:210px;object-fit:cover}.event-info{display:flex;flex:1;flex-direction:column;padding:23px}.event-info h2{margin:8px 0;font-size:22px}.event-meta{color:var(--primary-deep);font-size:12px;font-weight:700;text-transform:uppercase}.event-info p{color:var(--muted-foreground)}.event-more{margin-top:auto;color:var(--primary-deep);font-weight:700}@media(max-width:900px){.event-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){.event-grid{grid-template-columns:1fr}.cat-session{align-items:flex-start;flex-direction:column}}</style>
<section class="hero"><div class="wrap"><div class="crumbs"><a href="/idemaclima/">Home</a> / <a href="/idemaclima/campus">Campus</a> / Area CAT</div><span class="section-label">Formazione tecnica riservata</span><h1>Campus CAT</h1><p>Eventi e incontri riservati ai Centri Assistenza Tecnica IDEMA.</p></div></section>
<section class="content"><div class="wrap"><div class="cat-session"><div><strong><?= e($catUser['company_name']) ?></strong><br><span class="meta"><?= e($catUser['contact_first_name'].' '.$catUser['contact_last_name']) ?></span></div><form method="post" action="/idemaclima/campus/cat/logout"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><button class="btn" type="submit">Esci</button></form></div><div class="event-grid"><?php foreach($events as $event): ?><a class="event-card" href="/idemaclima/campus/cat/<?= e($event['slug']) ?>"><?php if(!empty($event['cover_image'])):?><img src="<?= e($event['cover_image']) ?>" alt="<?= e($event['title']) ?>"><?php endif; ?><div class="event-info"><span class="event-meta"><?= e(date('d/m/Y H:i',strtotime((string)$event['starts_at']))) ?><?= !empty($event['location'])?' · '.e($event['location']):'' ?></span><h2><?= e($event['title']) ?></h2><?php if(!empty($event['short_description'])):?><p><?= e($event['short_description']) ?></p><?php endif; ?><span class="event-more">Apri evento →</span></div></a><?php endforeach; ?><?php if(!$events): ?><p>Nessun evento CAT in programma.</p><?php endif; ?></div></div></section>
